        var line = mn.mergeDecisionLine({ prNumber: 1, headSha: HEAD, action: 'held' });
        assert.contains(line, 'machineThreads=0');
        assert.contains(line, 'humanThreads=0');
        assert.contains(line, 'allowlist=0');
    });
});

