+    });
+
+    test('a THROWN merge (scm fault) defers with its own line — lock released, labels stay', function () {
+        var r = withLogSpy(function () {
+            return runLane({
+                comments: [verdictComment('APPROVE', HEAD)],
+                prDetail: prDetail(),
+                mergeThrows: 'scm 504'
+            });
+        });
